class ControllerAdcEventRuntime final {
 using Q=AdcEventDequeueTask;using QS=Q::Stage;using C=AdcEventCalibrationTask;using CS=C::Stage;using T=AdcCalibrationTransformTask;using TS=T::Stage;
public:
 enum class Kind:uint8_t{Dequeue,Calibrate,Transform};enum class Block:uint8_t{None,NotBound,Inactive,NeedsInterrupt,UnsupportedMode};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};struct Range{uint32_t begin,end;};inline static constexpr std::array<Range,2>CodeRanges{{{0x5ee,0x638},{0x1fac,0x2036}}};
 bool bindVerifiedFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(2*CodeRanges.size()))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin)||!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return active_;}void reset(){queue_.reset();calibrate_.reset();transform_.reset();active_=false;event_=0;value_=0;}uint32_t event()const{return event_;}uint8_t value()const{return value_;}
 bool start(Kind kind,uint8_t channel=0,uint8_t value=0,uint32_t source=0,uint16_t bias=0){if(!bound_||active_)return false;event_=0;value_=value;channel_=channel;switch(kind){case Kind::Dequeue:queue_.emplace();break;case Kind::Calibrate:calibrate_.emplace(channel);break;case Kind::Transform:transform_.emplace(source,value,bias);break;default:return false;}active_=true;return true;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq)const{if(bound_!=&d||!irq.boundTo(d)||!active_||d.interruptMode2||d.pendingIrqsHigh||irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return 0;auto cr=credits(d);auto n=transform_?transform_->nextClocks(cr):calibrate_?calibrate_->nextClocks(cr):queue_->nextClocks(cr);return n?n+(d.pendingIrqs?1u:0u):0;}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,unsigned budget){if(bound_!=&d||!irq.boundTo(d))return {0,false,Block::NotBound};if(!active_)return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};auto total=nextClocks(d,irq);if(!total||budget<total)return {};auto arb=d.pendingIrqs?1u:0u;if(arb)(void)d.read8(0xfffff2);auto cost=total-arb;auto begin=d.cycles;auto cr=credits(d);auto read=[&](uint32_t a,unsigned width){unsigned n=bus(a,width,-1),used=0;int last=-1;uint32_t v=0;for(unsigned i=0;i<width;++i){auto q=(a+i)&0xffffff;used+=bus(q,1,last);last=history(q);d.cycles=begin+cost-n+used;v=(v<<8)|d.readResource(q);}return v;};auto write=[&](uint32_t a,uint32_t v,unsigned width){unsigned n=bus(a,width,d.lastWrite),used=0;int last=d.lastWrite;for(unsigned i=0;i<width;++i){auto q=(a+i)&0xffffff;used+=bus(q,1,last);last=history(q);d.cycles=begin+cost-n+used;d.lastWrite=last;d.writeResource(q,uint8_t(v>>(8*(width-i-1))));}};bool stack=false;
 if(transform_){auto stage=transform_->stage();stack=stage==TS::Retain;if(transform_->advanceBefore(cost,cr,[&](bool gain){return read(transform_->source()+(gain?1:0),1);})!=cost)return {};if(transform_->complete()){value_=transform_->result();transform_.reset();if(calibrate_)calibrate_->resume();else active_=false;}}
 else if(calibrate_){auto stage=calibrate_->stage();bool modulation=calibrate_->modulation();stack=stage==CS::RetainPointer||stage==CS::RetainBias||stage==CS::Transform;if(stage==CS::Invert)value_=uint8_t(~value_);if(stage==CS::Half)value_>>=1;if(calibrate_->advanceBefore(cost,cr)!=cost)return {};if(calibrate_->awaiting())transform_.emplace(modulation?0xc8b0:0xc8ae,value_,modulation?0:0x400);if(calibrate_->complete()){calibrate_.reset();if(queue_){event_=(event_&0xffff00ff)|(uint32_t(value_)<<8);queue_->resume();}else active_=false;}}
 else{auto stage=queue_->stage();stack=stage==QS::Retain||stage==QS::RetainPointer||stage==QS::Calibrate;if(queue_->advanceBefore(cost,cr,[&](bool head){return read(stage==QS::ReadEvent?0xc1d0+queue_->offset():head?0xc1cc:0xc1ce,2);},[&](unsigned v){write(0xc1ce,v,2);})!=cost)return {};if(stage==QS::ReadEvent){auto v=queue_->event();event_=0x10000u|v;channel_=uint8_t(v);value_=uint8_t(v>>8);}if(queue_->awaiting())calibrate_.emplace(channel_);if(queue_->complete()){queue_.reset();active_=false;}}
 d.cycles=begin+cost;d.lastRead=-1;if(stack)d.lastWrite=-1;return {total,!active_,Block::None};}
private:static int history(uint32_t a){a&=0xffffff;return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;}static unsigned bus(uint32_t a,unsigned width,int previous){unsigned n=0;for(unsigned i=0;i<width;++i){auto q=(a+i)&0xffffff;int h=history(q);if(h>=0){if((previous&1)||q!=uint32_t(previous|1))n+=q<0x400000?3:1;previous=h;}else{n+=q>=0xffffa0?1:3;previous=-1;}}return n;}
 FlashCredits credits(const ControllerDeviceState&d)const{FlashCredits cr;if(transform_){auto s=transform_->stage();cr.read=bus(transform_->source()+(s==TS::ReadGain?1:0),1,-1);}else if(queue_&&!calibrate_){auto s=queue_->stage();cr.read=bus(s==QS::ReadEvent?0xc1d0+queue_->offset():s==QS::ReadTail?0xc1ce:0xc1cc,2,-1);cr.write=bus(0xc1ce,2,d.lastWrite);}return cr;}
 ControllerDeviceState*bound_=nullptr;bool active_=false;std::optional<Q>queue_{};std::optional<C>calibrate_{};std::optional<T>transform_{};uint32_t event_=0;uint8_t channel_=0,value_=0;
};
